import {recommend} from './recommendation.mjs?v=2';
const root=document.getElementById('cabinet-root'),notice=document.getElementById('cabinet-notice');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={new:'Обращение',payment:'Оплата',discussion:'Бриф и обсуждение',materials:'Материалы',work:'В работе',review:'Согласование',access:'Доступы Яндекса',delivery:'Выдача результата',done:'Готово'};
const date=v=>new Date(v.replace(' ','T')+'Z').toLocaleString('ru-RU',{dateStyle:'medium',timeStyle:'short'});
let csrf='',me=null,ready=false,selected=null;
const endpoint=(action,extra='')=>'cabinet/api.php?action='+action+extra;
function tell(s=''){notice.textContent=s;}
async function api(action,data,extra=''){
 const options={credentials:'same-origin',cache:'no-store',headers:{}};
 if(data!==undefined){options.method='POST';options.headers['X-CSRF-Token']=csrf;if(data instanceof FormData)options.body=data;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}}
 const res=await fetch(endpoint(action,extra),options);let json;
 try{json=await res.json()}catch{throw new Error('Сервер не ответил. Повторите позже или напишите в Telegram.');}
 if(!res.ok)throw new Error(json.error||'Не удалось выполнить действие.');
 if(json.csrf)csrf=json.csrf;return json;
}
function form(id,title,fields,button){return `<form id="${id}" class="cabinet-card"><h2>${title}</h2>${fields}<p class="form-error" role="alert"></p><button class="primary" type="submit">${button}</button></form>`;}
const input=(label,name,type='text',attributes='')=>`<label>${label}<input name="${name}" type="${type}" ${attributes} required></label>`;
const email=()=>input('Email','email','email','autocomplete="email" maxlength="254"');
const password=(fresh=false)=>input(fresh?'Пароль — минимум 8 символов':'Пароль','password','password',`autocomplete="${fresh?'new-password':'current-password'}" ${fresh?'minlength="8"':''} maxlength="72"`);
const consent=()=>'<label class="consent"><input name="consent" type="checkbox" required><span>Согласен(на) с <a href="privacy" target="_blank" rel="noopener">политикой конфиденциальности</a> и обработкой информации для работы с моим проектом.</span></label>';
function bindForm(id,handler){const f=document.getElementById(id);f.addEventListener('submit',async e=>{e.preventDefault();const button=f.querySelector('[type="submit"]');button.disabled=true;const error=f.querySelector('.form-error');error.textContent='';try{await handler(Object.fromEntries(new FormData(f)),f)}catch(err){error.textContent=err.message}finally{button.disabled=false}});}
async function init(){try{const s=await api('status');ready=s.ready;me=s.user;if(!ready){tell('Кабинет готовится к подключению. Пока обсудить проект можно в Telegram.');root.innerHTML='<a class="primary" href="https://t.me/Elimorastudio" target="_blank" rel="noopener">Написать Эльвире ↗</a>';if(new URLSearchParams(location.search).has('setup'))install();return;}tell();if(location.hash.startsWith('#reset=')){reset();return;}if(me)await enterCabinet();else auth();}catch(e){tell(e.message);root.innerHTML='<a class="secondary" href="https://t.me/Elimorastudio">Связаться в Telegram ↗</a>';}}
async function enterCabinet(){if(!adminRole()&&new URLSearchParams(location.search).get('new')==='1'&&draft()){newOrder();return;}await dashboard();}
function auth(){
 root.innerHTML='<div class="cabinet-grid">'+form('login','Продолжим <em>проект.</em>',email()+password(), 'Войти')+form('register','Давайте <em>знакомиться.</em>',input('Как к вам обращаться','name','text','autocomplete="name" maxlength="120"')+email()+password(true)+consent(),'Создать аккаунт')+'</div><p class="cabinet-help">Есть аккаунт, но не помните пароль? <button class="cabinet-link" id="forgot">Восстановить доступ</button></p>';
 for(const id of ['login','register'])bindForm(id,async d=>{d.consent=d.consent==='on';const s=await api(id,d);me=s.user;await enterCabinet();});document.getElementById('forgot').onclick=forgot;
}
function forgot(){root.innerHTML=form('forgot-form','Восстановим <em>доступ.</em>',email(),'Отправить письмо')+'<p><button class="cabinet-link" id="back-auth">Назад ко входу</button></p>';bindForm('forgot-form',async d=>{const r=await api('forgot',d);tell(r.message)});document.getElementById('back-auth').onclick=()=>{tell();auth()};}
function reset(){const token=location.hash.slice(7);root.innerHTML=form('reset-form','Новый <em>пароль.</em>',password(true),'Сохранить пароль');bindForm('reset-form',async d=>{await api('reset',{...d,token});history.replaceState(null,'',location.pathname);tell('Пароль изменён. Войдите с новым паролем.');await init();tell('Пароль изменён. Войдите с новым паролем.');});}
const categories={media:{title:'Фото и видео',icon:'▧',accept:'.jpg,.jpeg,.png,.mp4,.mov',hint:'Фото PNG/JPEG · видео MP4/MOV',extensions:['jpg','jpeg','png','mp4','mov']},brand:{title:'Логотип и брендбук',icon:'◇',accept:'.jpg,.jpeg,.png,.webp,.svg,.pdf,.zip',hint:'Логотип, фирменные цвета, шрифты и требования',extensions:['jpg','jpeg','png','webp','svg','pdf','zip']},documents:{title:'Документы',icon:'▤',accept:'.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt',hint:'Прайсы, услуги и информация · PDF, Word, Excel',extensions:['pdf','doc','docx','xls','xlsx','csv','txt']}};
const money=v=>(Number(v)/100).toLocaleString('ru-RU',{style:'currency',currency:'RUB'});
const stagesFor=kind=>Object.entries(labels).filter(([key])=>key!=='access'||['maps','combined'].includes(kind));
const views={overview:'Обзор',projects:'Проекты',files:'Мои файлы',review:'На согласовании',payment:'Оплата',documents:'Документы'};
let orders=[],view='overview',uploading=false,projectTab='project',notifications=[];
const safe=fn=>async(...args)=>{try{await fn(...args)}catch(e){tell(e.message)}};
const canNavigate=()=>{if(!uploading)return true;tell('Дождитесь завершения загрузки. Материалы уже отправляются.');return false};
window.addEventListener('beforeunload',e=>{if(uploading){e.preventDefault();e.returnValue=''}});
function toolbar(){return `<div class="cabinet-toolbar"><p>${adminRole()?'Управление проектами':esc(me.name)+' · Личный кабинет'}</p><div class="cabinet-actions"><button class="secondary" id="refresh">Обновить</button><button class="secondary" id="logout">Выйти</button></div></div>`;}
function matches(o,v){return v==='review'?o.status==='review':true}
function shell(content){root.innerHTML=toolbar()+`<div class="cabinet-shell"><aside class="cabinet-sidebar"><p class="cabinet-sidebar-title">${sidebarTitle()}</p><nav aria-label="Разделы кабинета">${Object.entries(selected?{projects:'Проект',files:'Файлы',brief:'Подробный бриф',review:'Согласование',payment:'Оплата',documents:'Документы'}:views).filter(([key])=>!adminRole()||selected||key==='projects').map(([key,title])=>`<button data-view="${key}" ${key===view?'aria-current="page"':''}><span>${esc(viewTitle(key))}</span>${sidebarCount(key)}</button>`).join('')}</nav>${adminRole()?'':'<a class="cabinet-support" href="https://t.me/Elimorastudio" target="_blank" rel="noopener">Есть вопрос?<br><strong>Написать Эльвире ↗</strong></a>'}</aside><div class="cabinet-content">${notificationPanel()}${content}</div></div>`;bindToolbar();document.getElementById('read-notifications')?.addEventListener('click',safe(async()=>{await api('notifications-read',{});notifications=[];if(selected)await openOrder(selected,projectTab);else await dashboard(view)}));root.querySelectorAll('[data-view]').forEach(b=>b.onclick=safe(()=>navigateCabinet(b.dataset.view)));bindOrders();}
function bindToolbar(){document.getElementById('logout').onclick=safe(async()=>{if(!canNavigate())return;await api('logout',{});try{Object.keys(sessionStorage).filter(k=>k.startsWith('elimora-brief-draft:'+me.id+':')).forEach(k=>sessionStorage.removeItem(k))}catch{}me=null;await init()});document.getElementById('refresh').onclick=safe(async()=>{if(!canNavigate())return;if(selected)await openOrder(selected,projectTab);else await dashboard(view)});}
function bindOrders(){root.querySelectorAll('[data-order]').forEach(b=>b.onclick=safe(async()=>{if(canNavigate())await openOrder(Number(b.dataset.order),b.dataset.context||(view==='review'?'review':view==='payment'?'payment':view==='documents'?'documents':'project'))}));document.getElementById('new-order')?.addEventListener('click',()=>{if(canNavigate())newOrder()});}
function draft(){try{return JSON.parse(sessionStorage.getItem('elimora-order-draft')||'null')}catch{return null}}
function fromQuiz(){try{const a=JSON.parse(sessionStorage.getItem('elimora-brief-v2')||'null')?.answers;if(!a?.tasks?.length)return null;const r=recommend(a);return {answers:a,title:a.business?'Проект: '+a.business:'Оформление бизнеса',brief:['Сфера: '+r.sector,'Задачи: '+a.tasks.join(', '),r.pkg?'Рекомендация подбора: '+r.pkg.name+' — '+r.pkg.price+' ₽':'Нужен индивидуальный расчёт',...r.reasons,...r.warnings,a.notes||''].join('\n')}}catch{return null}}
function stepper(status,compact=false,kind='design'){const list=stagesFor(kind);const current=Math.max(0,list.findIndex(([key])=>key===status));return `<div class="project-progress ${compact?'compact':''}" aria-label="Ход проекта"><p>Этап ${current+1} из ${list.length} · ${esc(labels[status]||status)}</p>${compact?`<progress max="${list.length-1}" value="${current}" aria-label="Текущий этап проекта"></progress>`:`<ol style="--stages:${list.length}">${list.map(([key,s],i)=>`<li class="${i<current?'completed':i===current?'current':''}" ${i===current?'aria-current="step"':''}><span aria-hidden="true">${i<current?'✓':i+1}</span><small>${s}</small></li>`).join('')}</ol>`}</div>`;}

function orderCard(o){return `<button class="cabinet-order" data-order="${o.id}"><span class="cabinet-badge">${esc(labels[o.status]||o.status)}</span><strong>${esc(o.company||o.title)}</strong><span>№${o.id} · ${esc(o.title)}</span>${me.role==='admin'?`<span class="cabinet-date">${esc(o.name)} · ${esc(o.email)}</span>`:''}${stepper(o.status,true,o.kind)}<span class="cabinet-date">Обновлено: ${date(o.updated_at)}</span></button>`;}
async function dashboard(next='overview'){
 selected=null;view=next;const r=await api('orders');me=r.user;orders=r.orders;if(adminRole()&&view==='overview')view='projects';await loadNotifications();
 if(adminRole()){view='projects';adminQueue();return;}
 if(view==='payment'){const {payments}=await api('payments');shell(`<section class="cabinet-card"><h2>Оплата <em>проектов.</em></h2><p>${adminRole()?'Для нового счёта откройте клиента и раздел «Оплата» внутри проекта.':'Счета и QR-коды по каждому платежу. Получение денег подтверждает Эльвира.'}</p>${payments.length?payments.map(p=>paymentCard(p,true)).join(''):'<p class="cabinet-empty">Платежей пока нет. После согласования стоимости здесь появится счёт.</p>'}</section>`);return;}
 if(view==='documents'){const {files}=await api('files');shell(`<section class="cabinet-card"><h2>Документы <em>по проектам.</em></h2><p>Договоры, счета, QR-коды и акты. Все файлы сохраняются в своём проекте.</p>${documentFiles(files,true)}</section>`);bindDeletes(()=>dashboard('documents'));return;}
 if(view==='files'){const {files}=await api('files');shell(`<section class="cabinet-card"><h2>${adminRole()?'Файлы <em>клиента.</em>':'Все ваши <em>материалы.</em>'}</h2><p>${adminRole()?'Материалы, которые прислали клиенты. Внутри каждого проекта — фото и видео, логотип и брендбук, документы.':'Файлы из всех ваших проектов. Для добавления материалов откройте нужный проект.'}</p>${adminRole()?clientFilesGrouped(files):fileGroups(files.filter(f=>f.purpose==='material'||f.purpose==='final'),true)}</section>`);bindDeletes(()=>dashboard('files'));return;}

 const filtered=orders.filter(o=>matches(o,view));const intro=view==='overview'?`<p>${me.role==='admin'?'Проекты, материалы и этапы работы с клиентами.':'Здесь всё по вашему проекту: задача, материалы, обсуждение и текущий этап.'}</p><div class="cabinet-stats">${[['projects','Проекты'],['review','На согласовании']].map(([k,t])=>`<button data-view="${k}"><strong>${orders.filter(o=>matches(o,k)).length}</strong><span>${t}</span></button>`).join('')}</div>`:view==='review'?'<p>Здесь появятся проекты, когда Эльвира отправит результат на согласование. Откройте версию, посмотрите материалы и согласуйте их или отправьте список правок.</p>':'';
 shell(`<section class="cabinet-card"><div class="cabinet-heading"><h2>${esc(views[view])}</h2>${me.role!=='admin'?`<button class="primary" id="new-order">${draft()||fromQuiz()?'Продолжить оформление':'Новый проект'} +</button>`:''}</div>${intro}<div class="cabinet-list">${filtered.length?filtered.map(orderCard).join(''):`<p class="cabinet-empty">${view==='review'?'Пока нет проектов на согласовании.':'Пока проектов нет. Начните с кнопки «Новый проект».'}</p>`}</div></section>`);
}
function newOrder(){
 selected=null;const d=draft()||fromQuiz()||{};
 shell(form('new-project','Расскажите <em>о задаче.</em>',input('Название компании','company','text','autocomplete="organization" maxlength="200" placeholder="Например, кофейня «Зёрна»"')+input('Что нужно оформить или создать','title','text','maxlength="200" placeholder="Например, оформление профиля в Картах"')+'<label>Коротко о задаче и рекомендации подбора<textarea name="brief" maxlength="24000" rows="10" required></textarea></label><p class="cabinet-help">Рекомендация подбора — предварительная. Состав работ, стоимость и сроки согласуем до начала. Первичное общение доступно до оплаты. Подробный бриф и детальное обсуждение откроются после подтверждения первого платежа.</p>'+consent(),'Создать проект'));
 const f=document.getElementById('new-project');f.elements.company.value=d.company||d.answers?.business||'';f.elements.title.value=d.title||'';f.elements.brief.value=d.brief||'';
 bindForm('new-project',async v=>{const r=await api('create',{...v,consent:v.consent==='on',answers:d.answers||{}});try{sessionStorage.removeItem('elimora-order-draft')}catch{}if(new URLSearchParams(location.search).get('new')==='1')history.replaceState(null,'',location.pathname);tell('Проект создан. Добавьте материалы, а вопросы можно написать в обсуждении.');orders=(await api('orders')).orders;await openOrder(r.id);});
}
function fileGroups(files,global=false){if(!files.length)return '<p class="cabinet-empty">Материалов пока нет.</p>';return Object.entries(categories).map(([key,cat])=>{const list=files.filter(f=>(f.category||'documents')===key);return list.length?`<section class="file-category"><h3>${cat.title} <span>${list.length}</span></h3><div class="cabinet-files-grid">${list.map(f=>{const id=f.order_id||selected;const raster=['image/jpeg','image/png','image/webp'].includes(f.mime);return `<article class="file-tile"><a href="${endpoint('download','&id='+id+'&file='+f.id)}" class="file-download">${raster?`<img src="${endpoint('preview','&id='+id+'&file='+f.id)}" alt="" loading="lazy">`:`<span class="file-symbol" aria-hidden="true">${esc(f.original_name.split('.').pop().toUpperCase())}</span>`}<strong>${esc(f.original_name)}</strong><small>${(Number(f.bytes)/1048576).toFixed(2)} МБ · Скачать ↓</small></a>${global?`<button class="cabinet-link" data-order="${id}">${esc(f.company||f.title||'Проект №'+id)}</button>`:''}${me.role==='admin'||Number(f.user_id)===Number(me.id)?`<button class="cabinet-link file-delete" data-delete="${f.id}" data-project="${id}" aria-label="Удалить ${esc(f.original_name)}">Удалить</button>`:''}</article>`}).join('')}</div></section>`:''}).join('');}
function bindDeletes(refresh){root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=safe(async()=>{if(!canNavigate()||!confirm('Удалить этот материал из проекта?'))return;await api('delete-file',{},'&id='+b.dataset.project+'&file='+b.dataset.delete);await refresh()}));}
function uploadCards(){return `<div class="upload-options">${Object.entries(categories).map(([key,c])=>`<button type="button" class="upload-option" data-pick="${key}"><span class="upload-icon" aria-hidden="true">${c.icon}<b>+</b></span><strong>${c.title}</strong><span>${c.hint}</span><small>Выбрать до 30 файлов</small></button><input class="upload-input" id="pick-${key}" type="file" multiple accept="${c.accept}" aria-label="${c.title}">`).join('')}</div><p class="cabinet-help">Загрузка начнётся сразу после выбора. До 30 файлов за раз, до 150 МБ каждый. Фото HEIC предварительно сохраните в PNG или JPEG.</p><div id="upload-progress" aria-live="polite"></div>`;}
async function uploadBatch(id,category,selection,options={}){
 const filePurpose=options.purpose||"material",payment=options.payment||null,assetType=options.asset||"general";
 const categoryOf=f=>category||(/\.(pdf|docx?|xlsx?|csv|txt)$/i.test(f.name)?"documents":/\.(svg|webp|zip)$/i.test(f.name)?"brand":"media");
 const files=Array.from(selection);if(!files.length)return;
 const box=document.getElementById('upload-progress');
 if(files.length>30){box.textContent='Выберите до 30 файлов за один раз.';return;}
 const errors=[];let done=0;const valid=files.filter(f=>{const ext=f.name.split('.').pop().toLowerCase();if(!categories[categoryOf(f)].extensions.includes(ext)){errors.push(f.name+': '+(category==='media'?'фото принимаются только в PNG/JPEG, видео — MP4/MOV. HEIC нужно преобразовать.':'формат не подходит для этого раздела.'));return false}if(f.size<1||f.size>150*1048576){errors.push(f.name+': файл должен быть не больше 150 МБ и не пустым.');return false}return true});
 uploading=true;root.querySelectorAll('[data-pick],[data-upload]').forEach(b=>b.disabled=true);
 try{for(const file of valid){let token='';try{const started=await api('upload-begin',{name:file.name,size:file.size,category:categoryOf(file),purpose:filePurpose,payment,asset_type:assetType},'&id='+id);token=started.upload;let offset=0;while(offset<file.size){const progress=Math.round((done+offset/file.size)/valid.length*100);box.innerHTML=`<p><strong>Загружаем ${done+1} из ${valid.length}</strong> · ${esc(file.name)}</p><progress max="100" value="${progress}" aria-label="Прогресс загрузки">${progress}%</progress><p>${progress}% · Не закрывайте страницу до завершения.</p>`;const end=Math.min(offset+started.chunk_bytes,file.size);const data=new FormData();data.append('upload',token);data.append('offset',String(offset));data.append('chunk',file.slice(offset,end),'chunk.bin');const result=await api('upload-chunk',data,'&id='+id);offset=result.received;if(offset===file.size&&!result.complete)throw new Error('Сервер не подтвердил сохранение файла.');}done++;}catch(e){errors.push(file.name+': '+e.message);if(token)try{await api('upload-cancel',{upload:token},'&id='+id)}catch{}}}
 }finally{uploading=false;await openOrder(id,projectTab);const result=document.getElementById('upload-progress');result.innerHTML=`<p class="upload-result">Сохранено ${done} из ${files.length} файлов.</p>${errors.length?`<div class="form-error" role="alert">${errors.map(e=>`<p>${esc(e)}</p>`).join('')}<p>Успешно загруженные материалы уже сохранены. Повторно выберите только остальные файлы.</p></div>`:''}`;result.scrollIntoView({behavior:'smooth',block:'nearest'});}
}
async function loadNotifications(){notifications=(await api('notifications')).notifications;}
function notificationPanel(){const unseen=notifications.filter(n=>!Number(n.seen));return unseen.length?`<section class="cabinet-notifications" aria-label="Уведомления"><div><strong>Новые события · ${unseen.length}</strong><button class="cabinet-link" id="read-notifications">Отметить прочитанными</button></div>${unseen.slice(0,5).map(n=>`<button class="cabinet-event" data-order="${n.order_id}" data-context="${n.body.includes('согласован')?'review':n.body.includes('плат')||n.body.includes('счёт')?'payment':'project'}">${esc(n.body)} <span>Проект №${n.order_id} ↗</span></button>`).join('')}</section>`:'';}
const purposeNames={material:'Материалы клиента',review:'Версия для согласования',final:'Финальные файлы',contract:'Договор',invoice:'Счёт',qr:'QR-код для оплаты',act:'Акт выполненных работ'};
const paymentNames={pending:'Ожидает оплаты',reported:'Проверяем поступление',paid:'Оплачено',cancelled:'Отменён'};
function paymentCard(p,global=false,files=[]){const id=p.order_id||selected;return `<article class="payment-card ${p.status==='paid'?'is-paid':''}"><div class="payment-heading"><div><span class="cabinet-badge">${esc(paymentNames[p.status]||p.status)}</span><h3>${esc(p.title)}</h3>${global?`<p>${esc(p.company||p.project_title)} · Проект №${id}</p>`:''}</div><strong class="payment-amount ${Number(p.amount_minor)?'':'amount-in-file'}">${Number(p.amount_minor)?money(p.amount_minor):'Сумма — в счёте'}</strong></div>${p.note?`<p class="cabinet-brief">${esc(p.note)}</p>`:''}${global?`<button class="secondary" data-order="${id}" data-context="payment">Счёт и QR-код ↗</button>`:`${documentFiles(files.filter(f=>Number(f.payment_id)===Number(p.id)),false,true)}<div class="cabinet-actions">${me.role==='admin'?`${p.status!=='paid'&&p.status!=='cancelled'?`<button class="primary" data-payment="${p.id}" data-payment-state="paid">Подтвердить получение</button><button class="cabinet-link" data-payment="${p.id}" data-payment-state="cancelled">Отменить счёт</button>`:''}${p.status==='paid'?`<button class="cabinet-link" data-payment="${p.id}" data-payment-state="pending">Исправить: поступление не подтверждено</button>`:''}`:p.status==='pending'?`<button class="primary" data-payment="${p.id}" data-payment-state="reported">Я оплатил(а)</button>`:p.status==='reported'?'<p class="cabinet-help">Сообщение отправлено. Эльвира проверит поступление денег и подтвердит оплату.</p>':''}</div>`}</article>`;}
function documentFiles(files,global=false,quiet=false){const list=files.filter(f=>['contract','invoice','qr','act'].includes(f.purpose));return list.length?`<div class="document-list">${list.map(f=>{const id=f.order_id||selected;return `<article class="document-item"><div><span class="cabinet-badge">${purposeNames[f.purpose]}</span><strong>${esc(f.original_name)}</strong>${global?`<button class="cabinet-link" data-order="${id}" data-context="documents">${esc(f.company||f.title)} · Проект №${id}</button>`:''}${f.purpose==='qr'&&['image/png','image/jpeg'].includes(f.mime)?`<img class="payment-qr" src="${endpoint('preview','&id='+id+'&file='+f.id)}" alt="QR-код для оплаты по счёту">`:''}</div><a class="secondary" href="${endpoint('download','&id='+id+'&file='+f.id)}">Скачать ↓</a></article>`}).join('')}</div>`:quiet?'':'<p class="cabinet-empty">Документы появятся здесь, когда Эльвира добавит их в проект.</p>';}

function previewFile(f,o){const raster=['image/jpeg','image/png','image/webp'].includes(f.mime);const video=['video/mp4','video/quicktime'].includes(f.mime);const url=endpoint('preview','&id='+o.id+'&file='+f.id);return `<article class="review-file">${raster?`<a href="${url}" target="_blank" rel="noopener"><img src="${url}" alt="${esc(f.original_name)}" loading="lazy"></a>`:video?`<video controls preload="metadata" src="${url}"></video>`:`<a class="secondary" href="${url}" target="_blank" rel="noopener">Открыть PDF ↗</a>`}<strong>${esc(f.original_name)}</strong>${me.role==='admin'&&!f.review_id?`<button class="cabinet-link" data-delete="${f.id}" data-project="${o.id}">Удалить черновик</button>`:''}${(Number(o.released)||me.role==='admin')?`<a class="cabinet-link" href="${endpoint('download','&id='+o.id+'&file='+f.id)}">Скачать ↓</a>`:''}</article>`;}
function reviewPanel(o){const admin=me.role==='admin';const latest=o.reviews[0];const drafts=o.files.filter(f=>f.purpose==='review'&&!f.review_id),draftLinks=o.links.filter(l=>!l.review_id);return `<section class="cabinet-card"><h2>Согласование <em>результата.</em></h2><p>Просмотрите файлы версии. Все решения и комментарии сохраняются в истории проекта.</p>${admin?`${adminReviewUploads(o)}<div class="workflow-callout"><h3>Черновик новой версии</h3><p>${drafts.length||draftLinks.length?'Файлов: '+drafts.length+' · ссылок: '+draftLinks.length:'Добавьте работы нужного типа выше.'}</p>${reviewGroups(drafts,draftLinks,o)}<form id="publish-review"><label>Комментарий к версии<textarea name="note" maxlength="6000" placeholder="Что подготовлено и на что обратить внимание"></textarea></label><p class="form-error" role="alert"></p><button class="primary" type="submit" ${!(drafts.length||draftLinks.length)||latest?.state==='pending'?'disabled':''}>Отправить клиенту на согласование</button></form></div>`:''}${o.reviews.length?o.reviews.map((r,i)=>`<article class="review-version"><div class="cabinet-heading"><h3>Версия ${o.reviews.length-i}</h3><span class="cabinet-badge">${{pending:'Ждёт вашего решения',approved:'Согласовано',changes:'Запрошены правки'}[r.state]}</span></div><p class="cabinet-date">Отправлена: ${date(r.created_at)}</p>${r.note?`<p class="cabinet-brief">${esc(r.note)}</p>`:''}${reviewGroups(o.files.filter(f=>Number(f.review_id)===Number(r.id)),o.links.filter(l=>Number(l.review_id)===Number(r.id)),o)}${r.feedback?`<div class="review-feedback"><strong>Комментарий клиента</strong><p>${esc(r.feedback)}</p></div>`:''}${r.decided_at?`<p class="cabinet-date">Решение: ${date(r.decided_at)}</p>`:''}${!admin&&r.state==='pending'&&i===0?`<form id="review-response" data-review="${r.id}"><label>Правки или комментарий<textarea name="feedback" maxlength="6000" placeholder="Укажите файл и что именно нужно изменить. Для согласования комментарий необязателен."></textarea></label><p class="form-error" role="alert"></p><div class="cabinet-actions"><button class="secondary" type="submit" name="decision" value="changes">Отправить правки</button><button class="primary" type="submit" name="decision" value="approved">Всё хорошо — согласовано ✓</button></div></form>`:''}</article>`).join(''):'<p class="cabinet-empty">Материалы пока готовятся. Когда появится версия для просмотра, здесь будет уведомление и кнопки для ответа.</p>'}</section>`;}
function paymentPanel(o){return `<section class="cabinet-card"><h2>Оплата <em>проекта.</em></h2>${adminRole()?`<p>Прикрепите готовый счёт из Т-Банка. Сумма, реквизиты и QR-код остаются в вашем файле.</p>${uploadControl('new-invoice','Прикрепить счёт',{purpose:'invoice',accept:'.pdf,.doc,.docx',hint:'Готовый файл из банка · загрузится сразу после выбора'})}`:'<p>Откройте счёт, оплатите по указанным в нём реквизитам или QR-коду и нажмите «Я оплатил(а)». Эльвира подтвердит поступление денег.</p>'}${o.payments.length?o.payments.map(p=>paymentCard(p,false,o.files)).join(''):'<p class="cabinet-empty">Счёт пока не прикреплён.</p>'}</section>`;}

function accessPanel(o){if(!['maps','combined'].includes(o.kind)||!['access','delivery','done'].includes(o.status))return '';return `<section class="workflow-callout"><h3>Доступ к профилю Яндекс Бизнеса</h3><p>Для размещения согласованных материалов предоставьте доступ через приглашение представителя. Пароль от аккаунта передавать не нужно.</p>${o.access_note?`<p class="cabinet-brief">${esc(o.access_note)}</p>`:'<p>Эльвира добавит сюда адрес для приглашения и инструкции.</p>'}${Number(o.access_reported)?'<p class="cabinet-badge">Клиент сообщил о предоставлении доступа</p>':me.role!=='admin'&&o.status==='access'?'<button class="secondary" id="access-report">Доступ предоставлен</button>':''}</section>`;}
const briefFields={products:['Что вы предлагаете','Основные услуги или товары, приоритетные направления, цены'],goals:['Какую задачу должен решить проект','Что хотите изменить и какой результат важен для бизнеса'],audience:['Для кого вы работаете','Кто ваш клиент, что для него важно при выборе'],messages:['Что нужно рассказать клиентам','Преимущества, акции, условия, важные формулировки'],brand:['Стиль и фирменные материалы','Цвета, шрифты, настроение, что сохранить или исключить'],links:['Ссылки на бизнес','Сайт, Яндекс Карты, соцсети; для сайта — домен и нужные интеграции'],references:['Примеры, которые нравятся','Ссылки и объяснение, что именно понравилось'],constraints:['Требования и ограничения','Обязательные тексты, запреты, особенности согласования'],deadline:['Сроки и контакт для согласования','Желаемая дата, кто принимает решение и как с ним связаться']};
function briefPanel(o){const paid=o.payments.some(p=>p.status==='paid');const saved=o.detailed_brief,cached=briefDraft(o.id);const readonly=me.role==='admin'||['done','review','access','delivery'].includes(o.status);return `<section class="cabinet-card"><h2>Подробный <em>бриф.</em></h2><p>${adminRole()?'Клиент заполняет эту форму в своём кабинете после подтверждения оплаты и нажимает «Отправить бриф». Ответы автоматически появляются здесь; пересылать их отдельно не нужно.':'Заполните ответы и нажмите «Отправить бриф». Эльвира получит уведомление и увидит ваши ответы в этом же проекте.'}</p>${saved?`<a class="secondary" href="${endpoint('brief-download','&id='+o.id)}">Скачать бриф ↓</a>`:''}${saved?`<p class="cabinet-date">Последняя отправка: ${date(saved.created_at)}</p>`:''}${!paid&&!saved?`<div class="workflow-callout"><h3>Бриф откроется после оплаты</h3><p>Сначала уточним услугу, объём работ и стоимость. После подтверждения первого платежа вы сможете подробно рассказать о бизнесе, задачах и пожеланиях.</p><button class="primary" data-project-tab="payment">Перейти к оплате ↗</button><p class="cabinet-help">Вопросы по условиям можно задать в чате уже сейчас.</p></div>`:readonly?`${saved?Object.entries(briefFields).map(([k,[label]])=>`<div class="brief-answer"><h3>${label}</h3><p>${esc(saved.answers[k]||'Не указано')}</p></div>`).join(''):'<p class="cabinet-empty">Клиент ещё не отправил подробный бриф.</p>'}`:`<p>Расскажите о бизнесе и задаче. Первые три вопроса обязательны; остальные помогут точнее подготовить результат. ${['maps','combined'].includes(o.kind)?'Для Яндекс Карт особенно важны услуги, цены, преимущества и ссылки на профиль.':o.kind==='website'?'Для сайта опишите нужные страницы, действия посетителя и подключения.':'Для креативов укажите площадки, форматы и основные сообщения.'}</p><form id="detailed-brief"><p class="cabinet-help" id="brief-draft-status">Ответы сохраняются как черновик в этой вкладке браузера. Для передачи Эльвире нажмите «Отправить бриф».</p>${Object.entries(briefFields).map(([k,[label,hint]])=>`<label>${label}${['products','goals','audience'].includes(k)?' *':''}<textarea name="${k}" maxlength="2000" ${['products','goals','audience'].includes(k)?'required':''} placeholder="${hint}">${esc(cached[k]??saved?.answers[k]??'')}</textarea></label>`).join('')}<p class="form-error" role="alert"></p><button class="primary" type="submit">${saved?'Отправить обновлённый бриф':'Отправить бриф'}</button></form>`}</section>`;}
function projectPanel(o){const source=o.files.filter(f=>f.purpose==='material');const finals=o.files.filter(f=>f.purpose==='final'),deliverFiles=finals.length?finals:o.files.filter(f=>f.purpose==='review'&&Number(f.review_id)===Number(o.reviews[0]?.id));return `<section class="cabinet-card"><h2>Проект <em>и материалы.</em></h2>${accessPanel(o)}<details class="project-task" open><summary>Задача и рекомендации подбора</summary><div class="cabinet-brief">${esc(o.brief)}</div></details>${Number(o.released)?`<section class="workflow-callout"><h3>Проект завершён</h3><p>Финальные материалы доступны для скачивания.</p>${deliverFiles.length?fileGroups(deliverFiles):''}${reviewGroups([],o.links.filter(l=>Number(l.review_id)===Number(o.reviews[0]?.id)),o)}</section>`:''}<div class="workflow-callout"><h3>Подробности задачи</h3><p>${adminRole()?'Здесь появятся ответы клиента после отправки формы.':'Заполните подробный бриф после подтверждения первого платежа.'}</p><button class="secondary" data-project-tab="brief">${o.detailed_brief?'Открыть заполненный бриф':'Перейти к брифу'} ↗</button></div>${me.role==='admin'&&finals.length&&!Number(o.released)?`<section class="workflow-callout"><h3>Финальные файлы — пока доступны только вам</h3>${fileGroups(finals)}</section>`:''}${adminRole()?'<p><button class="secondary" data-project-tab="files">Открыть файлы клиента ↗</button></p>':'<h3>Материалы для работы</h3>'+fileGroups(source)}</section>`;}
function adminSettings(o){return me.role==='admin'?`<details class="admin-project-settings"><summary>Управление проектом</summary><form id="project-settings"><label>Тип проекта<select name="kind">${Object.entries({design:'Креативы и дизайн',maps:'Яндекс Карты',website:'Сайт',combined:'Комплексный проект с Яндекс Картами'}).map(([k,t])=>`<option value="${k}" ${k===o.kind?'selected':''}>${t}</option>`).join('')}</select></label><div class="project-plan-fields"><label>План старта<input type="date" name="planned_start" value="${esc(o.planned_start||'')}"></label><label>План завершения<input type="date" name="due_date" value="${esc(o.due_date||'')}"></label></div><p class="cabinet-help">Параллельно — до 3 проектов. Если оставить завершение пустым, оно рассчитается как 5 рабочих дней со старта (пн–пт). Оплата и полный комплект материалов нужны до начала.</p><label>Инструкция по доступу Яндекса<textarea name="access_note" maxlength="3000" placeholder="Адрес для приглашения и шаги клиента">${esc(o.access_note)}</textarea></label><p class="form-error" role="alert"></p><button class="secondary" type="submit">Сохранить настройки</button></form><div class="admin-stage"><label>Текущий этап<select id="project-status">${Object.entries(labels).filter(([k])=>!['review','done'].includes(k)||k===o.status).map(([k,v])=>`<option value="${k}" ${['review','done'].includes(k)?'disabled':''} ${k===o.status?'selected':''}>${v}</option>`).join('')}</select></label><button class="secondary" id="save-status">Изменить этап</button></div><p class="cabinet-help">Согласование запускается отправкой версии. После решения клиента этап изменится автоматически. Завершение — кнопкой выдачи результата.</p><button class="primary" id="release-project" ${o.reviews[0]?.state!=='approved'||Number(o.released)?'disabled':''}>Открыть скачивание и завершить проект</button></details>`:'';}
async function openOrder(id,tab='project'){
 const {order:o}=await api('order',undefined,'&id='+id);orders=(await api('orders')).orders;await loadNotifications();selected=id;projectTab=tab;view=tab==='project'?'projects':tab;
 const content=tab==='files'?`<section class="cabinet-card"><h2>${adminRole()?'Файлы <em>клиента.</em>':'Мои <em>файлы.</em>'}</h2>${fileGroups(o.files.filter(f=>f.purpose==='material'))}</section>`:tab==='brief'?briefPanel(o):tab==='review'?reviewPanel(o):tab==='payment'?paymentPanel(o):tab==='documents'?projectDocuments(o):projectPanel(o);
 shell(`<p><button class="cabinet-link" id="back-queue">${adminRole()?'← Все клиенты и очередь':'← Все мои проекты'}</button></p><section class="cabinet-card project-top"><span class="cabinet-badge">${esc(labels[o.status]||o.status)}</span><h2>${esc(o.company||o.title)}</h2><p>Проект №${o.id} · ${esc(o.title)}</p>${stepper(o.status,false,o.kind)}${me.role==='admin'?`<p>${esc(o.owner.name)} · ${esc(o.owner.email)}</p>`:''}${adminRole()?`<div class="project-plan-summary"><span>Обращение: ${date(o.created_at)}</span><span>Старт: ${shortDate(o.planned_start)}</span><span>Срок: ${shortDate(o.due_date)}</span></div>`:''}${adminSettings(o)}</section><div class="cabinet-workspace"><div class="project-primary">${content}${adminRole()||!['project','files'].includes(tab)?'<div id="upload-progress" aria-live="polite"></div>':''}${(!adminRole()&&['project','files'].includes(tab))?`<section class="cabinet-card material-upload"><h2>Добавить <em>файлы.</em></h2>${uploadCards()}</section>`:''}</div><section class="cabinet-card discussion-card"><h2>Обсуждение <em>проекта.</em></h2>${!o.payments.some(p=>p.status==='paid')?'<p class="cabinet-help">До оплаты уточняем услугу и условия. Подробный разбор задачи начнётся после подтверждения первого платежа.</p>':''}<div class="project-messages">${o.messages.length?o.messages.map(m=>`<article class="cabinet-message ${m.role==='admin'?'admin':''}"><strong>${esc(m.name)}</strong><small class="cabinet-date">${date(m.created_at)}</small><p>${esc(m.body)}</p></article>`).join(''):'<p>Здесь можно задать вопрос по проекту. Правки к версии отправьте во вкладке «Согласование».</p>'}</div><form id="message-form"><label>Сообщение<textarea name="body" maxlength="6000" required placeholder="Напишите о задаче или материалах…"></textarea></label><p class="form-error" role="alert"></p><button type="submit" class="primary">Отправить ↗</button></form><p class="cabinet-help">Нажмите «Обновить», чтобы проверить новые события.</p></section></div>`);
 document.getElementById('back-queue')?.addEventListener('click',safe(()=>{if(canNavigate())return dashboard('projects')}));
 bindForm('message-form',async d=>{if(!canNavigate())return;await api('message',d,'&id='+id);await openOrder(id,tab)});
 root.querySelectorAll('[data-project-tab]').forEach(b=>b.onclick=safe(async()=>{if(canNavigate())await openOrder(id,b.dataset.projectTab)}));
 root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{if(!uploading)document.getElementById('pick-'+b.dataset.pick).click()});
 for(const key of Object.keys(categories)){const picker=document.getElementById('pick-'+key);if(picker)picker.onchange=safe(async e=>{if(!uploading)await uploadBatch(id,key,e.target.files)})}
 root.querySelectorAll('[data-upload]').forEach(b=>{const picker=document.getElementById('target-'+b.dataset.upload);b.onclick=()=>{if(!uploading)picker.click()};picker.onchange=safe(async e=>{if(!uploading)await uploadBatch(id,null,e.target.files,{purpose:b.dataset.purpose,asset:b.dataset.asset,payment:b.dataset.uploadPayment||null})})});
 bindDeletes(()=>openOrder(id,tab));
 const action=async(name,data)=>{if(!canNavigate())return;await api(name,data,'&id='+id);await openOrder(id,tab)};
 if(document.getElementById('add-review-link'))bindForm('add-review-link',d=>action('link-add',d));
 root.querySelectorAll('[data-delete-link]').forEach(b=>b.onclick=safe(()=>action('link-delete',{link:Number(b.dataset.deleteLink)})));
 const briefForm=document.getElementById('detailed-brief');if(briefForm){briefForm.addEventListener('input',()=>{try{sessionStorage.setItem(briefDraftKey(id),JSON.stringify(Object.fromEntries(new FormData(briefForm))));document.getElementById('brief-draft-status').textContent='Черновик сохранён в этой вкладке. Для передачи Эльвире нажмите «Отправить бриф».'}catch{document.getElementById('brief-draft-status').textContent='Автосохранение недоступно. Не закрывайте форму до отправки.'}});bindForm('detailed-brief',async d=>{await action('brief-submit',d);try{sessionStorage.removeItem(briefDraftKey(id))}catch{}tell('Бриф отправлен. Эльвира получила уведомление и увидит ответы в вашем проекте.');});}
 if(document.getElementById('project-settings'))bindForm('project-settings',d=>action('project-settings',d));
 document.getElementById('save-status')?.addEventListener('click',safe(()=>action('status-change',{status:document.getElementById('project-status').value})));
 document.getElementById('release-project')?.addEventListener('click',safe(async()=>{if(confirm('Открыть клиенту финальные файлы и завершить проект?'))await action('release',{})}));
 document.getElementById('access-report')?.addEventListener('click',safe(()=>action('access-report',{})));
 if(document.getElementById('publish-review'))bindForm('publish-review',d=>action('review-publish',d));
 if(document.getElementById('create-payment'))bindForm('create-payment',d=>action('payment-create',{title:d.title,note:d.note,amount_minor:Math.round(Number(d.amount)*100)}));
 root.querySelectorAll('[data-payment]').forEach(b=>b.onclick=safe(async()=>{if(me.role==='admin'&&!confirm(b.dataset.paymentState==='paid'?'Подтверждаете поступление денег по этому платежу?':'Изменить статус этого платежа?'))return;await action('payment-update',{payment:Number(b.dataset.payment),status:b.dataset.paymentState})}));
 const response=document.getElementById('review-response');if(response)response.addEventListener('submit',async e=>{e.preventDefault();if(!canNavigate())return;const decision=e.submitter?.value;if(!['changes','approved'].includes(decision))return;const error=response.querySelector('.form-error');error.textContent='';const feedback=response.elements.feedback.value.trim();if(decision==='changes'&&!feedback){error.textContent='Опишите, что нужно изменить.';response.elements.feedback.focus();return;}if(decision==='approved'&&!confirm('Согласовать эту версию материалов?'))return;response.querySelectorAll('button').forEach(b=>b.disabled=true);try{await action('review-answer',{review:Number(response.dataset.review),decision,feedback})}catch(err){error.textContent=err.message;response.querySelectorAll('button').forEach(b=>b.disabled=false)}});
}

const briefDraftKey=id=>'elimora-brief-draft:'+me.id+':'+id;
function briefDraft(id){try{return JSON.parse(sessionStorage.getItem(briefDraftKey(id))||'{}')}catch{return {}}}
const assetNames={general:'Материалы',stories:'Истории',showcase:'Витрина',publications:'Публикации','qr-layout':'Макеты QR-кодов',multilink:'Мультиссылка',creative:'Креативы',logo:'Логотипы',website:'Сайт',final:'Финальные файлы'};
const adminRole=()=>me?.role==='admin';
const viewTitle=key=>key==='brief'?'Подробный бриф':selected&&key==='projects'?'Проект':adminRole()?({overview:'Обзор',projects:selected?'Проект':'Клиенты',files:'Файлы клиента',review:'Согласование',payment:'Оплата',documents:'Документы'}[key]||views[key]):views[key];
function uploadControl(key,title,{purpose='review',asset='general',payment='',accept='.jpg,.jpeg,.png,.webp,.pdf,.mp4,.mov',hint='До 30 файлов · загрузка сразу после выбора'}={}){return `<div class="target-upload"><button type="button" class="upload-option" data-upload="${key}" data-purpose="${purpose}" data-asset="${asset}" data-upload-payment="${payment}"><span class="upload-icon" aria-hidden="true">↥<b>+</b></span><strong>${title}</strong><span>${hint}</span></button><input class="upload-input" id="target-${key}" type="file" multiple accept="${accept}" aria-label="${title}"></div>`;}
function adminReviewUploads(o){const map=['maps','combined'].includes(o.kind);const types=map?['stories','showcase','publications','qr-layout']:o.kind==='website'?['website']:[];types.push('creative','logo');return `<div class="review-upload-tools"><h3>Добавить работы для согласования</h3><p>Файлы сначала сохраняются в черновике. Клиент увидит их после кнопки «Отправить на согласование».</p><div class="target-uploads">${types.map(type=>uploadControl(type,assetNames[type],{asset:type,hint:type==='stories'?'Вертикальные макеты и видео':type==='showcase'?'Квадратные макеты':type==='publications'?'Горизонтальные макеты и PDF':type==='logo'?'Изображения или PDF для просмотра':'Изображения, PDF или видео'})).join('')}</div><details class="link-editor" ${map?'open':''}><summary>${map?'Добавить мультиссылку':'Добавить ссылку на результат'}</summary><form id="add-review-link"><label>Название<input name="title" required maxlength="200" value="${map?'Мультиссылка':'Результат проекта'}"></label><label>Публичная ссылка<input name="url" type="url" required placeholder="https://…" maxlength="2000"></label><input type="hidden" name="asset_type" value="${map?'multilink':'website'}"><p class="form-error" role="alert"></p><button class="secondary" type="submit">Добавить в черновик</button></form></details><details class="final-upload"><summary>Добавить финальные файлы для выдачи</summary><p class="cabinet-help">Исходники, логотипы и архивы. Клиент сможет скачать их после завершения проекта.</p>${uploadControl('final','Финальные файлы и архивы',{purpose:'final',asset:'final',accept:'.jpg,.jpeg,.png,.webp,.svg,.pdf,.zip,.mp4,.mov,.doc,.docx,.xls,.xlsx,.txt,.csv'})}</details></div>`;}
function reviewGroups(files,links,o){return Object.entries(assetNames).map(([type,title])=>{const fs=files.filter(f=>(f.asset_type||'general')===type),ls=links.filter(l=>l.asset_type===type);if(!fs.length&&!ls.length)return '';return `<section class="review-type"><h4>${title}</h4><div class="review-gallery">${fs.map(f=>previewFile(f,o)).join('')}</div>${ls.map(l=>`<article class="review-link"><strong>${esc(l.title)}</strong><a class="secondary" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">Открыть ↗</a>${adminRole()&&!l.review_id?`<button class="cabinet-link" data-delete-link="${l.id}">Удалить черновик</button>`:''}</article>`).join('')}</section>`}).join('');}
function clientFilesGrouped(files){const source=files.filter(f=>f.purpose==='material');const ids=[...new Set(source.map(f=>Number(f.order_id)))];return ids.length?ids.map(id=>{const own=source.filter(f=>Number(f.order_id)===id),f=own[0];return `<section class="client-file-group"><h3><button class="cabinet-link" data-order="${id}" data-context="files">${esc(f.company||f.title)} · Проект №${id} ↗</button></h3>${fileGroups(own)}</section>`}).join(''):'<p class="cabinet-empty">Клиенты пока не загрузили материалы.</p>';}
const elapsed=(v,end=null)=>v?Math.max(0,Math.floor(((end?new Date(end.replace(' ','T')+'Z').getTime():Date.now())-new Date(v.replace(' ','T')+'Z').getTime())/86400000)):null;
const shortDate=v=>v?new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}):'Не назначено';
function deadlineLabel(o){if(!o.due_date)return 'Срок не назначен';const past=Date.now()>new Date(o.due_date+'T23:59:59').getTime();return (past&&o.status!=='done'?'Просрочен · ':'До ')+shortDate(o.due_date);}
let queueSearch='',queueFilter='active';
function queueRows(){const active=orders.filter(o=>o.status!=='done');const list=orders.filter(o=>(queueFilter==='all'||queueFilter==='done'&&o.status==='done'||queueFilter==='active'&&o.status!=='done'||queueFilter==='work'&&o.status==='work')&&[o.company,o.title,o.name,o.email,String(o.id)].join(' ').toLocaleLowerCase('ru').includes(queueSearch));return list.length?list.map(o=>{const days=o.status==='done'&&!o.completed_at?null:elapsed(o.work_started_at,o.status==='done'?o.completed_at:null);const overdue=o.status!=='done'&&o.due_date&&Date.now()>new Date(o.due_date+'T23:59:59').getTime();return `<tr class="${overdue?'queue-overdue':''}"><td data-label="Очередь">${o.status==='done'?'—':active.findIndex(x=>Number(x.id)===Number(o.id))+1}</td><td data-label="Клиент / проект"><button class="queue-client" data-order="${o.id}"><strong>${esc(o.company||o.name)}</strong><span>№${o.id} · ${esc(o.title)}</span></button><small>${esc(o.name)} · ${esc(o.email)}</small></td><td data-label="Этап"><span class="cabinet-badge">${esc(labels[o.status])}</span></td><td data-label="Обращение"><strong>${date(o.created_at)}</strong><small>${elapsed(o.created_at)} дн. с обращения</small></td><td data-label="В работе"><strong>${days===null?(['work','done'].includes(o.status)?'Дата не указана':'Ещё не начато'):days===0?'Первый день':days+' дн.'}</strong><small>${o.work_started_at?'С '+shortDate(o.work_started_at):o.planned_start?'Старт '+shortDate(o.planned_start):'Старт не назначен'}</small></td><td data-label="Срок"><strong>${deadlineLabel(o)}</strong><button class="cabinet-link" data-order="${o.id}">Открыть проект ↗</button></td></tr>`}).join(''):'<tr><td colspan="6" class="cabinet-empty">По выбранным условиям проектов нет.</td></tr>';}
function adminQueue(){const active=orders.filter(o=>o.status!=='done');shell(`<section class="cabinet-card queue-card"><h2>Очередь <em>клиентов.</em></h2><p>Первыми идут те, кто обратился раньше. Каждое повторное обращение — отдельный проект. Завершённые проекты сохраняются в истории.</p><div class="queue-summary"><span><strong>${active.length}</strong> открыто</span><span><strong>${active.filter(o=>o.status==='work').length}</strong> в работе</span><span><strong>${active.filter(o=>o.status==='review').length}</strong> на согласовании</span></div><div class="queue-filters"><label>Найти клиента<input id="queue-search" type="search" placeholder="Компания, имя, email или номер" value="${esc(queueSearch)}"></label><label>Показать<select id="queue-filter">${Object.entries({active:'Открытые проекты',work:'Только в работе',done:'Завершённые',all:'Вся история'}).map(([key,title])=>`<option value="${key}" ${queueFilter===key?'selected':''}>${title}</option>`).join('')}</select></label></div><div class="queue-table-wrap"><table class="queue-table"><thead><tr><th>№</th><th>Клиент / проект</th><th>Этап</th><th>Обращение</th><th>В работе</th><th>Срок</th></tr></thead><tbody id="queue-body">${queueRows()}</tbody></table></div><p class="cabinet-help">«В работе» считается с первого перехода на этот этап и не обнуляется при правках. Дни в таблице календарные. Для планирования: до 3 проектов одновременно, 5 рабочих дней на проект (пн–пт). План старта и срок назначаются в карточке проекта.</p></section>`);const update=()=>{document.getElementById('queue-body').innerHTML=queueRows();bindOrders()};document.getElementById('queue-search').oninput=e=>{queueSearch=e.target.value.toLocaleLowerCase('ru');update()};document.getElementById('queue-filter').onchange=e=>{queueFilter=e.target.value;update()};}
function sidebarTitle(){if(adminRole()&&selected){const o=orders.find(o=>Number(o.id)===Number(selected));return esc(o?.company||o?.title||'Проект')+'<small>Проект №'+selected+'</small>'}return adminRole()?'Управление':'Мой кабинет';}
function sidebarCount(key){if(adminRole()&&selected){return key==='review'?'<small>'+(orders.find(o=>Number(o.id)===Number(selected))?.status==='review'?1:0)+'</small>':''}return ['projects','review'].includes(key)?'<small>'+orders.filter(o=>matches(o,key)).length+'</small>':'';}
async function navigateCabinet(key){if(!canNavigate())return;if(selected){const tabs={projects:'project',files:'files',brief:'brief',review:'review',payment:'payment',documents:'documents'};if(tabs[key])return openOrder(selected,tabs[key]);}return dashboard(key);}
function projectDocuments(o){return `<section class="cabinet-card"><h2>Документы <em>проекта.</em></h2>${adminRole()?`<p>Здесь добавляются договоры и акты. Счета и QR-коды добавляются в разделе «Оплата» и также сохраняются в списке документов.</p><div class="target-uploads">${uploadControl('contract','Добавить договор',{purpose:'contract',accept:'.pdf,.doc,.docx',hint:'PDF или Word'})}${uploadControl('act','Добавить акт',{purpose:'act',accept:'.pdf,.doc,.docx',hint:'PDF или Word'})}</div>`:''}${documentFiles(o.files)}</section>`;}

function install(){root.innerHTML=form('install-form','Подключение <em>кабинета.</em>','<p>Только для владельца сайта. Сначала сохраните конфигурацию за пределами public_html.</p>'+input('Ключ установки из конфигурации','key','password','autocomplete="off" minlength="32"')+input('Ваше имя','name','text','autocomplete="name"')+password(true),'Создать кабинет администратора');bindForm('install-form',async d=>{await api('install',d);history.replaceState(null,'',location.pathname);await init();tell('Установка завершена. Войдите с email из конфигурации и только что созданным паролем.');});}
init();
